   colloFull:[{zh:'精通音乐',py:'jīngtōng yīnyuè',vn:'tinh thông âm nhạc'},{zh:'精通外语',py:'jīngtōng wàiyǔ',vn:'thông thạo ngoại ngữ'},{zh:'精通业务',py:'jīngtōng yèwù',vn:'thạo nghiệp vụ'},{zh:'精通……之人',py:'jīngtōng……zhī rén',vn:'người tinh thông …'},{zh:'精通电脑技术',py:'jīngtōng diànnǎo jìshù',vn:'thạo kỹ thuật máy tính'}],
