   exList:[{zh:'这首歌旋律简单，歌词好记，很快就在年轻人中流行起来了。',py:'Zhè shǒu gē xuánlǜ jiǎndān, gēcí hǎo jì, hěn kuài jiù zài niánqīngrén zhōng liúxíng qǐlai le.',vn:'Bài hát này giai điệu đơn giản, lời dễ nhớ, rất nhanh đã thịnh hành trong giới trẻ.'},
    {zh:'当琴声变得清新流畅时，打柴人说：“这旋律表达的是无尽的流水。”',py:'Dāng qínshēng biàn de qīngxīn liúchàng shí, dǎchái rén shuō: “Zhè xuánlǜ biǎodá de shì wújìn de liúshuǐ.”',vn:'Khi tiếng đàn trở nên trong trẻo, trôi chảy, người đốn củi nói: "Giai điệu này thể hiện dòng nước chảy bất tận."'},
    {zh:'一听到这熟悉的旋律，我就想起了中学时代。',py:'Yì tīngdào zhè shúxī de xuánlǜ, wǒ jiù xiǎngqǐle zhōngxué shídài.',vn:'Vừa nghe giai điệu quen thuộc này, tôi liền nhớ lại thời trung học.'}],
